private void processDirectory(File root, File folder, ByteBuddy byteBuddy, EntryPoint entryPoint, MethodNameTransformer methodNameTransformer, ClassFileLocator classFileLocator, TypePool typePool, List<Plugin> plugins) {
    File[] file = folder.listFiles();
    if (file != null) {
        for (File aFile : file) {
            try {
                if (aFile.isDirectory()) {
                    processDirectory(root, aFile, byteBuddy, entryPoint, methodNameTransformer, classFileLocator, typePool, plugins);
                } else if (aFile.isFile() && aFile.getName().endsWith(CLASS_FILE_EXTENSION)) {
                    processClassFile(root, root.toURI().relativize(aFile.toURI()).toString(), byteBuddy, entryPoint, methodNameTransformer, classFileLocator, typePool, plugins);
                } else {
                    project.getLogger().debug("Skipping ignored file: {}", aFile);
                }
            } catch (SecurityException e) {
                project.getLogger().debug("SecurityException while processing file: {}", aFile, e);
            } catch (IndexOutOfBoundsException e) {
                project.getLogger().debug("IndexOutOfBoundsException while processing file: {}", aFile, e);
            } catch (IllegalStateException e) {
                project.getLogger().debug("IllegalStateException while processing file: {}", aFile, e);
            }
        }
    }
}
